/* binary.js — cover art: 0/1 glyph grid forming MASK / CLOUD / LOCK / AI
   Renderer ported from component.html, recoloured for the white-green deck. */
(function () {
  'use strict';
  var SIZE = 300, CELL = 6, DPR = 2;
  var SHAPES = ['mask', 'cloud', 'lock', 'ai'];
  var LABELS = { mask: 'MASK', cloud: 'CLOUD', lock: 'LOCK', ai: 'AI' };

  function drawCloud(ctx) {
    ctx.beginPath();
    ctx.moveTo(70, 215);
    ctx.bezierCurveTo(28, 215, 28, 152, 78, 152);
    ctx.bezierCurveTo(72, 100, 128, 82, 152, 122);
    ctx.bezierCurveTo(168, 78, 222, 84, 226, 130);
    ctx.bezierCurveTo(272, 122, 278, 200, 232, 215);
    ctx.lineTo(70, 215);
    ctx.closePath();
    ctx.fill();
  }

  function drawLock(ctx) {
    ctx.lineCap = 'round';
    ctx.lineWidth = 20;
    ctx.beginPath();
    ctx.arc(150, 130, 46, Math.PI, Math.PI * 2);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(104, 130); ctx.lineTo(104, 162);
    ctx.moveTo(196, 130); ctx.lineTo(196, 162);
    ctx.stroke();
    ctx.beginPath();
    if (ctx.roundRect) ctx.roundRect(85, 155, 130, 112, 12);
    else ctx.rect(85, 155, 130, 112);
    ctx.fill();
    ctx.save();
    ctx.globalCompositeOperation = 'destination-out';
    ctx.beginPath();
    ctx.arc(150, 195, 14, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(143, 195); ctx.lineTo(136, 238); ctx.lineTo(164, 238); ctx.lineTo(157, 195);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  function drawAI(ctx) {
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = '900 168px "Helvetica Neue", Arial, system-ui, sans-serif';
    ctx.fillText('AI', 150, 158);
  }

  var CANVAS_SHAPES = { cloud: drawCloud, lock: drawLock, ai: drawAI };

  function BinaryArt(canvas, maskImg) {
    var self = this;
    this.canvas = canvas;
    this.maskImg = maskImg;
    this.ctx = canvas.getContext('2d');
    canvas.width = SIZE * DPR;
    canvas.height = SIZE * DPR;
    this.ctx.scale(DPR, DPR);

    this.cellW = CELL;
    this.cellH = CELL;
    this.cols = Math.floor(SIZE / CELL);
    this.rows = Math.floor(SIZE / CELL);

    this.maskCanvas = document.createElement('canvas');
    this.maskCanvas.width = SIZE;
    this.maskCanvas.height = SIZE;
    this.maskCtx = this.maskCanvas.getContext('2d');

    this.tempCanvas = document.createElement('canvas');
    this.tempCanvas.width = SIZE * DPR;
    this.tempCanvas.height = SIZE * DPR;
    this.tempCtx = this.tempCanvas.getContext('2d');

    this.digits = []; this.brightness = []; this.accent = [];
    for (var y = 0; y < this.rows; y++) {
      this.digits[y] = []; this.brightness[y] = []; this.accent[y] = [];
      for (var x = 0; x < this.cols; x++) {
        this.digits[y][x] = Math.random() < 0.5 ? '0' : '1';
        this.brightness[y][x] = 0.5 + Math.random() * 0.5;
        this.accent[y][x] = Math.random() < 0.16;
      }
    }

    this.grid = [];
    this.glitch = 0;
    this.shapeIdx = 0;
    this.lastFlip = 0;
    this.lastRender = 0;
    this.label = document.getElementById('shapeName');
    this.lastTransition = performance.now();

    this.tick = this.tick.bind(this);
    this.setShape(0);
    requestAnimationFrame(this.tick);
  }

  BinaryArt.prototype.setShape = function (idx) {
    this.shapeIdx = ((idx % SHAPES.length) + SHAPES.length) % SHAPES.length;
    var name = SHAPES[this.shapeIdx];
    var mc = this.maskCtx;
    mc.clearRect(0, 0, SIZE, SIZE);
    mc.fillStyle = '#fff';
    mc.strokeStyle = '#fff';
    if (name === 'mask') mc.drawImage(this.maskImg, 0, 0, SIZE, SIZE);
    else CANVAS_SHAPES[name](mc);
    this.computeGrid();
    this.triggerGlitch(1.0);
    if (this.label) this.label.textContent = LABELS[name];
  };

  BinaryArt.prototype.computeGrid = function () {
    var data = this.maskCtx.getImageData(0, 0, SIZE, SIZE).data;
    this.grid = [];
    for (var y = 0; y < this.rows; y++) {
      this.grid[y] = [];
      for (var x = 0; x < this.cols; x++) {
        var on = 0;
        for (var sy = 1; sy <= 3; sy++) {
          for (var sx = 1; sx <= 3; sx++) {
            var px = Math.min(SIZE - 1, Math.floor(x * this.cellW + (sx / 4) * this.cellW));
            var py = Math.min(SIZE - 1, Math.floor(y * this.cellH + (sy / 4) * this.cellH));
            var i = (py * SIZE + px) * 4;
            var lum = 0.299 * data[i] + 0.587 * data[i + 1] + 0.114 * data[i + 2];
            if (data[i + 3] > 128 && lum > 15) on++;
          }
        }
        this.grid[y][x] = on / 9 > 0.4;
      }
    }
  };

  BinaryArt.prototype.triggerGlitch = function (a) {
    this.glitch = Math.min(1.5, Math.max(this.glitch, a));
  };

  BinaryArt.prototype.tick = function (now) {
    var self = this;
    if (now - this.lastRender < 33) { requestAnimationFrame(this.tick); return; }
    this.lastRender = now;

    if (now - this.lastFlip > 120) {
      this.lastFlip = now;
      var flips = Math.floor(this.cols * this.rows * 0.05);
      for (var i = 0; i < flips; i++) {
        var x = Math.floor(Math.random() * this.cols);
        var y = Math.floor(Math.random() * this.rows);
        this.digits[y][x] = Math.random() < 0.5 ? '0' : '1';
        this.brightness[y][x] = 0.5 + Math.random() * 0.5;
      }
    }

    if (now - this.lastTransition > 4200) {
      this.lastTransition = now;
      this.setShape(this.shapeIdx + 1);
    }
    if (Math.random() < 0.002) this.triggerGlitch(0.22);

    this.render();

    if (this.glitch > 0) {
      this.glitch *= 0.94;
      if (this.glitch < 0.02) this.glitch = 0;
    }
    requestAnimationFrame(this.tick);
  };

  BinaryArt.prototype.render = function () {
    var ctx = this.ctx;
    ctx.clearRect(0, 0, SIZE, SIZE);
    ctx.font = 'bold 6.8px "Courier New", monospace';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    var halfW = this.cellW / 2, halfH = this.cellH / 2;
    for (var y = 0; y < this.rows; y++) {
      var row = this.grid[y];
      if (!row) continue;
      for (var x = 0; x < this.cols; x++) {
        if (!row[x]) continue;
        var b = this.brightness[y][x];
        ctx.fillStyle = this.accent[y][x]
          ? 'rgba(16,185,129,' + (0.62 + b * 0.36) + ')'
          : 'rgba(4,35,26,' + (0.5 + b * 0.5) + ')';
        ctx.fillText(this.digits[y][x], x * this.cellW + halfW, y * this.cellH + halfH);
      }
    }
    if (this.glitch > 0.02) this.applyGlitch();
  };

  BinaryArt.prototype.applyGlitch = function () {
    var ctx = this.ctx, bw = SIZE * DPR, bh = SIZE * DPR, t = this.tempCtx;
    t.clearRect(0, 0, bw, bh);
    t.drawImage(this.canvas, 0, 0);
    ctx.save();
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    var k = Math.min(1.2, this.glitch);
    var slices = 1 + Math.floor(3 * k);
    for (var i = 0; i < slices; i++) {
      var sy = Math.random() * bh;
      var sh = 8 + Math.random() * 36 * k;
      var dx = (Math.random() - 0.5) * 32 * k;
      ctx.drawImage(this.tempCanvas, 0, sy, bw, sh, dx, sy, bw, sh);
    }
    ctx.restore();
  };

  var canvas = document.getElementById('fawkes');
  if (!canvas) return;
  var blob = new Blob([GUY_FAWKES_SVG], { type: 'image/svg+xml;charset=utf-8' });
  var url = URL.createObjectURL(blob);
  var img = new Image();
  img.onload = function () {
    URL.revokeObjectURL(url);
    new BinaryArt(canvas, img);
  };
  img.onerror = function (e) { console.error('binary.js: mask svg failed', e); };
  img.src = url;
})();
